using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// Console entry point for the auto-wrong census (F-428 P12.13). Kept as an explicit method rather
/// than top-level statements so the golden test drives the exact host the CLI runs.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs the census command line and returns the process exit code.</summary>
	/// <param name="args">The raw command-line arguments.</param>
	/// <param name="output">Writer for the TSV; defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Writer for the summary and refusals; defaults to <see cref="System.Console.Error"/>.</param>
	/// <returns>The exit code: 0 on success, 1 on a missing trace, a refused set, or a usage error.</returns>
	public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null)
	{
		ArgumentNullException.ThrowIfNull(args);

		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output ?? System.Console.Out, error ?? System.Console.Error);
		var host = builder.Build();

		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync().ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
"}

