/// <summary>One classified auto-wrong line — the TSV row the census emits.</summary>
public sealed record CensusRow
{
	/// <summary>Holdout recipe id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (debug or batch).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation between the accepted row and the key row (brief §4 order, first match wins).</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Decision site: reuse, override, curated, or ranker.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>For override-site lines: whether the normalised rawText is a key in exact-overrides.json.</summary>
	/// <remarks>Empty for every other site.</remarks>
	/// <returns>yes/no for override lines, empty otherwise.</returns>
	public string OverrideKey { get; init; } = string.Empty;

	/// <summary>Dataset tier of the accepted row.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Dataset tier of the key row.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Accepted row's combined <c>FoodState</c> mask (state + satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Key row's combined <c>FoodState</c> mask (state + satisfiers).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Key head phrase: the key description's leading tokens up to the first production state/modifier word.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Accepted row description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Key row description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>Raw line text.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>Qualifier words present on the key row but not the accepted row (relation <c>same-head-other-qualifier</c>).</summary>
	/// <remarks>Not emitted in the TSV; used by the stderr summary.</remarks>
	/// <returns>Key-only qualifier tokens, or empty.</returns>
	public IReadOnlyList<string> KeyOnlyQualifiers { get; init; } = [];

	/// <summary>Qualifier words present on the accepted row but not the key row (relation <c>same-head-other-qualifier</c>).</summary>
	/// <remarks>Not emitted in the TSV; used by the stderr summary.</remarks>
	/// <returns>Accepted-only qualifier tokens, or empty.</returns>
	public IReadOnlyList<string> AcceptedOnlyQualifiers { get; init; } = [];

	/// <summary>Renders the row as a TSV line (tab/newline characters in text fields are folded to spaces).</summary>
	/// <returns>The TSV line, without a trailing newline.</returns>
	public string ToTsvLine()
	{
		static string Clean(string value) => value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');

		return string.Join('\t', HoldoutId, LineIndex, Set, Relation, Site, OverrideKey, AcceptedTier, KeyTier, AcceptedState, KeyState, ParsedName, KeyHead, AcceptedDesc, KeyDesc, RawText);
	}

	/// <summary>The TSV header matching <see cref="ToTsvLine"/>.</summary>
	/// <returns>The header line.</returns>
	public static string Header() => "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";
}
