{"content":"using System.Collections.Frozen;
using System.IO;
using System.Text.Json;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The raw-key set of <c>Lexicon/Resources/exact-overrides.json</c>, read from the embedded resource of
/// the production <c>LetUsCook.Fdc</c> assembly — the file itself, not a copy of its keys.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	/// <summary>A raw override key: trimmed, lower-cased, cut at the first <c>'('</c>.</summary>
	/// <remarks>
	/// Parity with <c>FdcMatcher</c>'s override lookup, which cuts the ingredient text at the first
	/// parenthesis before testing the raw-key table (private <c>StripFromParenthesis</c>,
	/// <c>FdcMatcher.cs:1360</c>; not reachable from outside the assembly, hence this one line here).
	/// </remarks>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The key form used by the matcher's raw-key lookup.</returns>
	public static string NormalizeOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var lowered = rawText.Trim().ToLowerInvariant();
		var paren = lowered.IndexOf('(', StringComparison.Ordinal);
		return paren >= 0 ? lowered[..paren].Trim() : lowered;
	}

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the shipped exact-overrides table from the Fdc assembly's embedded resources.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Lexicon.FdcLexicon).Assembly;
		var name = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(name)
			?? throw new InvalidOperationException($"Embedded resource '{name}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, OverrideEntry>>(reader.ReadToEnd())
			?? throw new InvalidOperationException("exact-overrides.json was empty.");

		_keys = entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Whether the normalized raw text is a raw key in <c>exact-overrides.json</c>.</summary>
	/// <param name="key">The normalized key.</param>
	/// <returns><see langword="true"/> when the key is present.</returns>
	public bool Contains(string key) => _keys.Contains(key);

	private sealed record OverrideEntry(string DataType, long FdcId);
}
