{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the relation between the accepted row and the
/// key (labelled) row, and the decision site. Every grammatical judgement goes through the
/// production helpers — <see cref="FdcNormalizer.NormalizeToTokens"/>, <see cref="FdcMatcher.ExtractCandidateState"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>, <see cref="FdcDescriptionParser.Parse"/> and
/// <see cref="IngredientLineResolver.SingularizeToken"/> — never a copy of them (D-014).
/// </summary>
/// <remarks>Not thread-safe: the scratch buffer in <see cref="CarriesStateToken"/> assumes one caller.</remarks>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the key row is empty.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: a can/jar unit in the raw text, <c>Canned</c> state on the key row, none on the accepted row.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase has two or more words and the parsed name kept only its first.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: heads agree after singularising, state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree, dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads agree and nothing above holds; the qualifier sets differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: the catch-all, used when a field a check needs is missing from the trace.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: the line reused a linked row through the ranker path.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: the override table decided the row.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: the curated catalogue decided the row.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Site: the ranker picked the row without reuse.</summary>
	public const string SiteRanker = "ranker";

	private static readonly FdcDataset[] NoDataset = [];

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly string?[] _singleTokenScratch = new string[1];

	/// <summary>Builds the classifier over the production normalizer and the shipped override key set.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">Keys of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_ = NoDataset;
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one auto-wrong line: first relation rule that holds wins (brief §4 order).</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, site and the audit fields the TSV carries.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = line.Atoms.FirstOrDefault(a => string.Equals(a.Outcome, "accepted", StringComparison.OrdinalIgnoreCase))
			?? line.Atoms.FirstOrDefault();
		var site = atom is null ? string.Empty : atom.Path switch
		{
			"override" => SiteOverride,
			"curated" => SiteCurated,
			"ranker" => atom.Reused ? SiteReuse : SiteRanker,
			_ => string.Empty
		};

		var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
		var acceptedDesc = line.ActualDescriptions.Count > 0 ? line.ActualDescriptions[0] : string.Empty;
		var keyTier = line.ExpectedDataTypes.Count > 0 ? line.ExpectedDataTypes[0] : string.Empty;
		var acceptedTier = line.ActualDataTypes.Count > 0 ? line.ActualDataTypes[0] : string.Empty;

		var relation = RelationOther;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;
		string keyHead = string.Empty;
		FoodState keyState = FoodState.None;
		FoodState acceptedState = FoodState.None;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else
		{
			var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
			var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
			keyState = CombinedState(keyTokens);
			acceptedState = CombinedState(acceptedTokens);

			var keyParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
			var acceptedParsed = string.IsNullOrWhiteSpace(acceptedDesc)
				? new ParsedFdcDescription(string.Empty, [], null)
				: FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));

			var keyHeadPhrase = KeyHeadPhrase(keyTokens);
			keyHead = string.Join(' ', keyHeadPhrase);
			var parsedNameTokens = Singularize(_normalizer.NormalizeToTokens(atom?.ParsedName));

			if (PackUnitRegex().IsMatch(line.RawText)
				&& (keyState & FoodState.Canned) != 0
				&& (acceptedState & FoodState.Canned) == 0)
			{
				relation = RelationPackUnitState;
			}
			else if (keyHeadPhrase.Count >= 2
				&& parsedNameTokens.Count == 1
				&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
			{
				relation = RelationCompoundHeadLost;
			}
			else if (HeadsAgree(keyParsed.HeadTerm, acceptedParsed.HeadTerm))
			{
				if (acceptedState != keyState)
				{
					relation = RelationStateMismatch;
				}
				else if (string.IsNullOrEmpty(keyTier) || string.IsNullOrEmpty(acceptedTier))
				{
					relation = RelationOther;
					missingField = string.IsNullOrEmpty(acceptedTier) ? "actualDataTypes" : "expectedDataTypes";
				}
				else if (acceptedTier != keyTier)
				{
					relation = RelationRowChoiceTier;
				}
				else
				{
					relation = RelationSameHeadOtherQualifier;
                    keyOnlyQualifiers = Difference(acceptedParsed.Qualifiers, keyParsed.Qualifiers);
                    acceptedOnlyQualifiers = Difference(keyParsed.Qualifiers, acceptedParsed.Qualifiers);
                }
			}
			else
			{
				relation = RelationSiblingFood;
			}
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = relation,
			Site = site,
			OverrideKey = site == SiteOverride ? (_overrideKeys.IsKey(NormalizeOverrideKey(line.RawText)) ? "yes" : "no") : string.Empty,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = keyHead,
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers
		};
	}

	/// <summary>
	/// The key row's head phrase: the leading normalised tokens up to the first token the production
	/// state machinery classifies as a state or modifier word (<c>dry</c>, <c>blanched</c>, <c>crushed</c>…).
	/// <c>Bread, crumbs, dry, grated, plain</c> → <c>bread crumbs</c>.
	/// </summary>
	/// <param name="tokens">Normalised tokens of the key description.</param>
	/// <returns>The singularised head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
            if (CarriesStateToken(token))
            {
                break;
            }

            phrase.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return phrase;
	}

	/// <summary>State ∪ satisfiers for a description's tokens, exactly as the matcher combines them in <c>StateAgrees</c>.</summary>
	/// <param name="tokens">Normalised tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Dataset tier for a trace dataType string; unknown strings parse as <see cref="FdcDataset.None"/>.</summary>
	/// <param name="tier">The dataType value from the trace.</param>
	/// <returns>The matching <see cref="FdcDataset"/>.</returns>
	public static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse<FdcDataset>(tier, out var dataset) ? dataset : FdcDataset.None;

	/// <summary>Tier rank used for the row-choice-tier summary: Foundation &gt; SrLegacy &gt; Survey &gt; Branded.</summary>
	/// <param name="tier">The dataType value from the trace.</param>
	/// <returns>4 for Foundation down to 1 for Branded; 0 for anything else.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0
	};

	/// <summary>
	/// The fold the matcher uses for raw-key override lookup: lower-case, trimmed, everything from the
	/// first <c>(</c> dropped. <c>FdcMatcher.StripFromParenthesis</c> is private, so this mirrors it
	/// (brief §8); the key set itself is the shipped file, not a copy.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeOverrideKey(string rawText)
	{
		if (string.IsNullOrEmpty(rawText))
		{
			return string.Empty;
		}

		var cut = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = cut >= 0 ? rawText[..cut] : rawText;
#pragma warning disable CA1308 // Reason: override keys are lower-case in exact-overrides.json; parity with FdcMatcher's nameClean fold.
		return text.Trim().ToLowerInvariant();
#pragma warning restore CA1308
	}

	/// <summary>Whether two head terms agree after normalising and singularising.</summary>
	/// <param name="left">Head term from one description.</param>
	/// <param name="right">Head term from the other.</param>
	/// <returns><see langword="true"/> when the token sequences are equal.</returns>
	private bool HeadsAgree(string left, string right) =>
		Singularize(_normalizer.NormalizeToTokens(left)).SequenceEqual(
			Singularize(_normalizer.NormalizeToTokens(right)), StringComparer.OrdinalIgnoreCase);

	private bool CarriesStateToken(string token)
	{
		_singleTokenScratch[0] = token;
		return FdcLexicon.Default.ModifierWords.Contains(token)
			|| FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> Singularize(IReadOnlyList<string> tokens)
	{
		var result = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			result.Add(IngredientLineResolver.SingularizeToken(token));
		}

		return result;
	}

	private static IReadOnlyList<string> Difference(IReadOnlyList<string> source, IReadOnlyList<string> other)
		=> source.Where(t => !other.Contains(t, StringComparer.OrdinalIgnoreCase)).OrderBy(t => t, StringComparer.Ordinal).ToList();

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();
}
