{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Executes one census or pairs invocation and returns the process exit code.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the configured subcommand.</summary>
	/// <param name="cancellationToken">The cancellation token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or unusable arguments.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>
/// The P12.13 instrument: reads a HoldoutGate trace, classifies every auto-wrong line
/// (<c>auto &amp;&amp; !correct</c>) by accepted-row vs key-row relation and site, and writes the
/// per-line TSV to the output sink with the relation × site summary on the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly System.IO.TextWriter _output;
	private readonly System.IO.TextWriter _error;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="normalizer">The production normalizer (used by the pairs head fold).</param>
	/// <param name="output">TSV sink.</param>
	/// <param name="error">Summary and diagnostics sink.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		System.IO.TextWriter output,
		System.IO.TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_output = output;
		_error = error;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = _options.Value;

		if (options.Command is not (CommandLineArgumentParser.CensusCommand or CommandLineArgumentParser.PairsCommand))
		{
			_error.WriteLine("refused: unusable arguments. Expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'.");
			return 1;
		}

		if (options.Command == CommandLineArgumentParser.CensusCommand)
		{
			return RunCensus(options.TracePath, cancellationToken);
		}

		if (!System.IO.File.Exists(options.CensusTsvPath))
		{
			_error.WriteLine($"refused: census TSV not found at '{options.CensusTsvPath}'.");
			return 1;
		}

		return RunPairs(options.CensusTsvPath, options.TracePath, cancellationToken);
	}

	private int RunCensus(string tracePath, CancellationToken cancellationToken)
	{
		var lines = ReadTrace(tracePath);
		if (lines is null)
		{
			return 1;
		}

		if (RefusedSet(lines) is { } refused)
		{
			return 1;
		}

		_output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");

		var results = new List<ClassificationResult>();
		foreach (var line in lines)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!line.Auto || line.Correct)
			{
				continue;
			}

			var result = _classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				_error.WriteLine($"refused: unknown atom path '{line.Atoms[0].Path}' on {line.HoldoutId}#{line.LineIndex}; the census cannot attribute a site.");
				return 1;
			}

			results.Add(result);
			_output.WriteLine(ToTsvLine(result));
		}

		WriteSummary(results);
		return 0;
	}

	private int RunPairs(string censusPath, string tracePath, CancellationToken cancellationToken)
	{
		var lines = ReadTrace(tracePath);
		if (lines is null)
		{
			return 1;
		}

		if (RefusedSet(lines) is { })
		{
			return 1;
		}

		var traceByKey = new Dictionary<(string, int), TraceLine>(lines.Count);
		foreach (var line in lines)
		{
			traceByKey[(line.HoldoutId, line.LineIndex)] = line;
		}

		var censusRows = ReadCensusRows(censusPath);
		if (censusRows is null)
		{
			return 1;
		}

		_output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		var unmatched = 0;
		foreach (var (holdoutId, lineIndex) in censusRows)
		{
			cancellationToken.ThrowIfCancellationRequested();
			if (!traceByKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(keyDesc)));

			_output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		_error.WriteLine($"pairs: emitted {emitted} window compound/other rows; {unmatched} census rows had no trace line.");
		return 0;
	}

	private IReadOnlyList<TraceLine>? ReadTrace(string tracePath)
	{
		if (!System.IO.File.Exists(tracePath))
		{
			_error.WriteLine($"refused: trace file not found at '{tracePath}'.");
			return null;
		}

		var lines = new List<TraceLine>();
		var lineNumber = 0;
		foreach (var raw in System.IO.File.ReadLines(tracePath))
		{
			lineNumber++;
			if (string.IsNullOrWhiteSpace(raw))
			{
				continue;
			}

			try
			{
				var parsed = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
				if (parsed is null)
				{
					_error.WriteLine($"refused: trace line {lineNumber} of '{tracePath}' is not a trace record.");
					return null;
				}

				lines.Add(parsed);
		 }
			catch (JsonException ex)
			{
				_error.WriteLine($"refused: trace line {lineNumber} of '{tracePath}' is not valid JSON: {ex.Message}");
				return null;
			}
		}

		return lines;
	}

	private static string? RefusedSet(IReadOnlyList<TraceLine> lines)
	{
		foreach (var line in lines)
		{
			if (line.Set is not ("debug" or "batch"))
			{
				Console.Error.WriteLine($"refused: trace set '{line.Set}' (D-029: only debug/batch traces may be classified).");
				return line.Set;
			}
		}

		return null;
	}

	private IReadOnlyList<(string HoldoutId, int LineIndex)>? ReadCensusRows(string censusPath)
	{
		var rows = new List<(string, int)>();
		var header = System.IO.File.ReadLines(censusPath).First();
		var columns = header.Split('\t');
		var idIndex = Array.IndexOf(columns, "holdoutId");
		var lineIndexPos = Array.IndexOf(columns, "lineIndex");
		var blockerIndex = Array.IndexOf(columns, "blocker");
		var routeIndex = Array.IndexOf(columns, "route");
		if (idIndex < 0 || lineIndexPos < 0 || blockerIndex < 0 || routeIndex < 0)
		{
			_error.WriteLine($"refused: census TSV '{censusPath}' lacks holdoutId/lineIndex/blocker/route columns.");
			return null;
		}

		foreach (var raw in System.IO.File.ReadLines(censusPath).Skip(1))
		{
			var fields = raw.Split('\t');
			if (fields.Length <= Math.Max(blockerIndex, routeIndex))
			{
                continue;
            }

			var blocker = fields[blockerIndex];
            var route = fields[routeIndex];
            if (blocker == "window" && (route == "compound" || route == "other"))
            {
                rows.Add((fields[idIndex], int.Parse(fields[lineIndexPos])));
            }
        }

        return rows;
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : "unknown";
		_error.WriteLine($"auto-wrong census set={set} autoWrongLines={results.Count}");

		var matrix = results
			.GroupBy(r => (r.Relation, r.Site))
			.OrderBy(g => g.Key.Relation)
			.ThenBy(g => g.Key.Site);
		_error.WriteLine("relation\tsite\tcount");
		foreach (var group in matrix)
		{
			_error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var otherCount = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		_error.WriteLine($"other share: {otherCount}/{results.Count} ({(results.Count > 0 ? otherCount * 100.0 / results.Count : 0):F1}%)");

		var missingFields = results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!);
		_error.WriteLine("missing trace fields: " + (missingFields.Any()
			? string.Join(", ", missingFields.Select(g => $"{g.Key}={g.Count()}"))
			: "none");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		_error.WriteLine($"override-site lines: {overrideLines.Count}; rawText is an exact-overrides.json key: {overrideLines.Count(r => r.OverrideKey == "yes")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse && r.ParsedName.Length > 0 && !string.IsNullOrEmpty(r.HoldoutId)).ToList();
		var shouldReuseFalse = 0;
		foreach (var result in reuseLines)
		{
            // The trace does not carry the linked master slug in the TSV, but the classification
            // loop has the atom only through the line; the summary recomputes from the line's
            // parsedName vs the accepted-row head — see ReuseSlugMatches below.
            _ = shouldReuseFalse;
        }

		var tierRows = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier);
		var keyHigher = tierRows.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
		var acceptedHigher = tierRows.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier));
		_error.WriteLine($"row-choice-tier: key tier higher={keyHigher}, accepted tier higher={acceptedHigher}");

		_error.WriteLine("same-head-other-qualifier detail:");
		foreach (var result in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			_error.WriteLine($"  {result.HoldoutId}#{result.LineIndex} key-only=[{string.Join(",", result.KeyOnlyQualifiers ?? [])}] accepted-only=[{string.Join(",", result.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string ToTsvLine(ClassificationResult result) =>
		string.Join('\t',
			Sanitize(result.HoldoutId),
			result.LineIndex,
			Sanitize(result.Set),
			Sanitize(result.Relation),
			Sanitize(result.Site),
			Sanitize(result.OverrideKey),
			Sanitize(result.AcceptedTier),
			Sanitize(result.KeyTier),
			Sanitize(result.AcceptedState),
			Sanitize(result.KeyState),
			Sanitize(result.ParsedName),
			Sanitize(result.KeyHead),
			Sanitize(result.AcceptedDesc),
			Sanitize(result.KeyDesc),
			Sanitize(result.RawText));

	private static string Sanitize(string value) =>
		value.Replace('\t', ' ').Replace('\r', ' ').Replace('\n', ' ');

	private static class JsonSerializer
	{
		public static TraceLine? Deserialize(string raw, JsonSerializerOptions options) =>
			JsonSerializerImpl.Deserialize(raw, options);

		private static class JsonSerializerImpl
		{
			public static TraceLine? Deserialize(string raw, JsonSerializerOptions options) =>
				System.Text.Json.JsonSerializer.Deserialize<TraceLine>(raw, options);
		}
	}
